<template>
  <div class="page-bulk-register">
    <div class="crud-toolbar">
      <h2 class="title">{{ t('nodes.bulk.title') }}</h2>
    </div>

    <el-alert
      v-if="errorMessage"
      :title="errorMessage"
      type="error"
      show-icon
      closable
      @close="errorMessage = ''"
      style="margin-bottom: 16px"
    />

    <el-card>
      <el-tabs v-model="activeTab">
        <el-tab-pane :label="t('nodes.bulk.tabFile')" name="file">
          <el-form label-width="100px">
            <el-form-item :label="t('nodes.bulk.file')">
              <el-upload
                ref="uploadRef"
                :auto-upload="false"
                :limit="1"
                :on-change="onFileChange"
                :on-remove="onFileRemove"
                accept=".csv,.json"
              >
                <el-button type="primary">{{ t('nodes.bulk.chooseFile') }}</el-button>
                <template #tip>
                  <div class="upload-tip">
                    {{ t('nodes.bulk.uploadTip') }}
                  </div>
                </template>
              </el-upload>
            </el-form-item>
            <el-form-item>
              <el-button type="primary" :loading="submitting" @click="submitFile">
                {{ t('nodes.bulk.startImport') }}
              </el-button>
            </el-form-item>
          </el-form>
        </el-tab-pane>

        <el-tab-pane :label="t('nodes.bulk.tabJson')" name="json">
          <el-form label-width="100px">
            <el-form-item :label="t('nodes.bulk.jsonText')">
              <el-input
                v-model="jsonText"
                type="textarea"
                :rows="10"
                placeholder='{"nodes": [{"name": "web-01", "host": "192.168.1.101", "platform": "linux"}]}'
              />
            </el-form-item>
            <el-form-item>
              <el-button type="primary" :loading="submitting" @click="submitJson">
                {{ t('nodes.bulk.startImport') }}
              </el-button>
            </el-form-item>
          </el-form>
        </el-tab-pane>
      </el-tabs>
    </el-card>

    <el-card v-if="result" style="margin-top: 20px">
      <template #header>
        <div class="result-header">
          <span>{{ t('nodes.bulk.resultTitle') }}</span>
          <el-button
            v-if="result.success_count > 0"
            type="success"
            size="small"
            @click="downloadScript"
          >
            {{ t('nodes.bulk.downloadScript') }}
          </el-button>
        </div>
      </template>

      <el-descriptions :column="3" border>
        <el-descriptions-item :label="t('nodes.bulk.total')">{{ result.total_count }}</el-descriptions-item>
        <el-descriptions-item :label="t('common.success')">
          <el-tag type="success">{{ result.success_count }}</el-tag>
        </el-descriptions-item>
        <el-descriptions-item :label="t('common.failed')">
          <el-tag :type="result.failure_count > 0 ? 'danger' : 'info'">
            {{ result.failure_count }}
          </el-tag>
        </el-descriptions-item>
      </el-descriptions>

      <el-table :data="result.results" style="margin-top: 16px" max-height="400">
        <el-table-column prop="name" :label="t('nodes.nodeName')" min-width="140" />
        <el-table-column prop="node_id" :label="t('nodes.nodeId')" min-width="180" />
        <el-table-column prop="status" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.status === 'success' ? 'success' : 'danger'">
              {{ row.status === 'success' ? t('common.success') : t('common.failed') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="error" :label="t('nodes.bulk.errorMessage')" min-width="240">
          <template #default="{ row }">
            <span v-if="row.error" class="error-message">{{ row.error }}</span>
            <span v-else>-</span>
          </template>
        </el-table-column>
      </el-table>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import type { UploadFile, UploadInstance } from 'element-plus'
import {
  bulkCreateNodes,
  bulkCreateNodesFromCsv,
  getBulkInstallScriptUrl,
  type BulkNodeCreateResponse,
} from '@/api/nodes'
import { showError } from '@/utils/error'

const { t } = useI18n()

const activeTab = ref<'file' | 'json'>('file')
const uploadRef = ref<UploadInstance>()
const selectedFile = ref<File | null>(null)
const jsonText = ref('')
const submitting = ref(false)
const errorMessage = ref('')
const result = ref<BulkNodeCreateResponse | null>(null)

function onFileChange(uploadFile: UploadFile) {
  selectedFile.value = uploadFile.raw || null
}

function onFileRemove() {
  selectedFile.value = null
}

async function submitFile() {
  if (!selectedFile.value) {
    ElMessage.warning(t('nodes.bulk.selectFileWarning'))
    return
  }

  errorMessage.value = ''
  submitting.value = true
  try {
    const file = selectedFile.value
    if (file.name.toLowerCase().endsWith('.csv')) {
      result.value = await bulkCreateNodesFromCsv(file)
    } else if (file.name.toLowerCase().endsWith('.json')) {
      const text = await file.text()
      const data = JSON.parse(text)
      result.value = await bulkCreateNodes(data)
    } else {
      throw new Error(t('nodes.bulk.onlyCsvJson'))
    }
    ElMessage.success(t('nodes.bulk.importDone', { success: result.value.success_count, failed: result.value.failure_count }))
  } catch (error) {
    showError(error, t('nodes.bulk.importFailed'))
    errorMessage.value = t('nodes.bulk.importFailedDetail')
  } finally {
    submitting.value = false
  }
}

async function submitJson() {
  if (!jsonText.value.trim()) {
    ElMessage.warning(t('nodes.bulk.jsonRequired'))
    return
  }

  errorMessage.value = ''
  submitting.value = true
  try {
    const data = JSON.parse(jsonText.value)
    result.value = await bulkCreateNodes(data)
    ElMessage.success(t('nodes.bulk.importDone', { success: result.value.success_count, failed: result.value.failure_count }))
  } catch (error) {
    showError(error, t('nodes.bulk.importFailed'))
    errorMessage.value = t('nodes.bulk.jsonParseFailed')
  } finally {
    submitting.value = false
  }
}

function downloadScript() {
  if (!result.value) return
  const url = getBulkInstallScriptUrl(result.value.task_id)
  window.open(url, '_blank')
}
</script>

